def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'
    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    opp_d = opp.count('D')
    if n >= 10 and opp_d >= n * 0.8:
        return 'D'
    last_unprov = -1
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and (i == 0 or opp[i-1] == 'C'):
            last_unprov = i
            break
    if last_unprov != -1:
        if last_unprov == n - 1:
            return 'C'
        if opp[last_unprov + 1] == 'C':
            return 'D'
        else:
            if last_unprov >= n - 3:
                return 'C'
    tests = 0
    for i in range(n):
        if me[i] == 'D' and (i == 0 or opp[i-1] == 'C'):
            if i < n - 1 and opp[i+1] == 'D':
                tests += 1
    if tests >= 5:
        if opp[-1] == 'D':
            cons_opp_d = 0
            for x in reversed(opp):
                if x == 'D':
                    cons_opp_d += 1
                else:
                    break
            cons_my_d = 0
            for x in reversed(me):
                if x == 'D':
                    cons_my_d += 1
                else:
                    break
            if cons_opp_d >= 3 and cons_my_d >= 2:
                return 'C'
            return 'D'
        else:
            return 'C'
    if n >= 15 and rng.random() < 0.1:
        return 'D'
    if opp[-1] == 'D':
        cons_opp_d = 0
        for x in reversed(opp):
            if x == 'D':
                cons_opp_d += 1
            else:
                break
        cons_my_d = 0
        for x in reversed(me):
            if x == 'D':
                cons_my_d += 1
            else:
                break
        if cons_opp_d >= 3 and cons_my_d >= 2:
            return 'C'
        return 'D'
    else:
        return 'C'
